@push('scripts')
<script>
document.querySelectorAll('.print-barcode').forEach(button => button.addEventListener('click', () => {
    const card = button.closest('.variant-card');
    const rows = Math.max(1, Math.min(500, Number(card.querySelector('.barcode-print-controls input').value) || 1));
    const csrf = document.querySelector('meta[name="csrf-token"]').content;
    const originalText = button.textContent;
    button.disabled = true;
    button.textContent = 'Printing…';
    fetch(button.dataset.printUrl, {method: 'POST', headers: {'Accept': 'application/json', 'Content-Type': 'application/json', 'X-CSRF-TOKEN': csrf}, body: JSON.stringify({rows})})
        .then(async response => { const result = await response.json(); if (!response.ok) throw new Error(result.message || 'Could not print barcode labels.'); window.showToast(result.message, 'success'); })
        .catch(error => window.showToast(error.message))
        .finally(() => { button.disabled = false; button.textContent = originalText; });
}));
</script>
@endpush
